import type { ProductRepository } from '../../domain/repositories/ProductRepository';
import type { CatalogueItemDto } from './ProductDtos';
import { toCatalogueItemDto } from './ProductMapper';

export interface ListCatalogue {
  execute(): CatalogueItemDto[];
}

export class ListCatalogueUseCase implements ListCatalogue {
  constructor(private readonly products: ProductRepository) {}

  execute(): CatalogueItemDto[] {
    return this.products.findAll().map(toCatalogueItemDto);
  }
}

